tool_input.command:
env NODE_ENV=test bun -e "
import { Database } from 'bun:sqlite'
const db = new Database('./data/guren.test.db')
const u = db.query('select id from users limit 1').get()
db.run(\"insert into posts (title, excerpt, body, author_id, created_at, published_at) values ('Later', 'e', 'b', ?, '2026-01-01T00:00:00.000Z', '2027-01-01T00:00:00.000Z'), ('Sooner', 'e', 'b', ?, '2026-01-01T00:00:00.000Z', '2026-12-01T00:00:00.000Z'), ('Past', 'e', 'b', ?, '2026-01-01T00:00:00.000Z', '2020-01-01T00:00:00.000Z')\", [u.id, u.id, u.id])
"; env NODE_ENV=test bun run console posts:scheduled 2>/dev/null | cat -A; echo "exit ${pipestatus[1]}"
